function isListItem(line, index2, allLines) {
  if (line.trim().startsWith("•")) return true;
  if (index2 > 0 && allLines[index2 - 1].trim().endsWith(":")) {
    return line.length < 80 && !line.endsWith(".");
  }
  return false;
}
function processFaqAnswer(answer) {
  const result = [];
  let currentList = [];
  for (const [index2, line] of answer.entries()) {
    const cleanLine = line.replace(/^•\s*/, "").trim();
    if (isListItem(line, index2, answer)) {
      currentList.push(cleanLine);
    } else {
      if (currentList.length > 0) {
        result.push({ type: "list", content: currentList });
        currentList = [];
      }
      if (cleanLine) result.push({ type: "text", content: cleanLine });
    }
  }
  if (currentList.length > 0)
    result.push({ type: "list", content: currentList });
  return result;
}
